new CrossoverEpisode(11,"갈라진 전선","jahmir","legretta","두 부대의 전투를 순차 진행하고 합류. 한 전장에 보스 2명을 강제 배치하지 않음.",new[]{new StoryLine("기록","봉쇄는 전열을 두 갈래로 나눴다. 서쪽에서는 자미르가 길을 뒤틀고, 동쪽에서는 리그렛이 사선을 조였다."),new StoryLine("제이드","먼저 서쪽 중계기를 확보합니다. 그 신호로 동쪽 부대의 길을 열 수 있습니다."),new StoryLine("자미르","발밑이 바뀌어도 앞으로 갈 수 있을까?"),new StoryLine("티아","리그렛은 혼란을 이용해 자기 임무를 수행하고 있어. 오르도의 명령을 받는다고 단정하지 마."),new StoryLine("키사라","한 전선씩 확보하자. 합류 신호가 올 때까지 서로를 믿는다.")},new[]{new StoryLine("리그렛","지휘관의 계획을 꺾을 생각이라면 다음 전장에서 증명해라."),new StoryLine("티아","나는 명령만 따르던 때로 돌아가지 않겠어. 내 눈으로 본 사람들을 지킬 거야."),new StoryLine("제이드","두 부대의 신호가 이어졌습니다. 모두 돌아왔군요."),new StoryLine("기록","자미르와 리그렛은 각자의 방향으로 물러났다. 두 전선은 순차적으로 돌파되었고 열 명이 다시 모였다.")}),
new CrossoverEpisode(12,"만들어진 낙원","van","","복제 장치 정지와 반의 패배. 원본 세계의 존속 선택.",new[]{new StoryLine("반","무너질 원본을 붙들 이유는 없다. 새 세계에는 같은 실수를 남기지 않겠다."),new StoryLine("티아","오빠가 고른 평온을 위해 지금 살아 있는 사람들을 지울 수는 없어."),new StoryLine("제이드","복제 기술을 안다고 생명의 가치를 대신 결정할 수 있는 것은 아닙니다."),new StoryLine("나탈리아","불완전해도 우리가 살아 온 세계예요. 그곳으로 돌아갈 권리를 지키겠어요."),new StoryLine("반","그렇다면 성역의 장치를 넘어 내게 와라.")},new[]{new StoryLine("반","끝까지 원본의 미래를 선택하겠다는 것이냐."),new StoryLine("티아","오빠가 내게 가르친 노래도 그 세계에서 만난 사람들도 지우지 않을 거야."),new StoryLine("제이드","복제 장치를 멈췄습니다. 남아 있는 생명은 누구도 지우지 않습니다."),new StoryLine("기록","반은 물러났고 일행은 원래 세계의 존속을 선택했다. 오르도의 보존과도 다른 답이었다.")}),
new CrossoverEpisode(13,"누구의 세계를 먼저 구할 것인가","shigure","","구출 순서 선택, 선택을 지킬 힘의 결투. 순서만 달라지고 구출 불가 분기 없음.",new[]{new StoryLine("기록","두 피난로가 동시에 무너지고 있었다. 어느 쪽을 먼저 열어도 나머지 길로 돌아올 수 있도록 연락망을 남겼다."),new StoryLine("시구레","선택은 누구나 하지. 끝까지 책임질 힘이 있는지 보자."),new StoryLine("벨벳","네 결투에 사람들을 걸 생각은 없어. 먼저 구조 순서를 정하겠어."),new StoryLine("키사라","두 번째 행렬도 버리지 않는다. 방패를 남기고 먼저 길을 연다."),new StoryLine("시구레","좋아. 그 약속을 지킬 검을 보여라.")},new[]{new StoryLine("시구레","인정하지. 네 칼끝은 흔들리지 않았어. 남은 길도 가 봐라."),new StoryLine("벨벳","네가 평가해 주길 바란 적 없어. 이제 다른 행렬을 데리러 가야 해."),new StoryLine("키사라","두 행렬 모두 안전 구역에 도착했다. 선택은 순서였지, 버릴 사람을 고르는 일이 아니었다."),new StoryLine("기록","시구레와의 결투는 여기서 끝났다. 그의 원래 세계에 남은 싸움의 결말을 대신하지는 않았다.")}),
new CrossoverEpisode(14,"적과 맺는 약속","dhaos","","재전 뒤 증거를 제시하고 조건부 공조. 전용 무기 최종 시련 개방.",new[]{new StoryLine("다오스","또 내 앞을 막는가. 말로 내 세계를 되살릴 수는 없다."),new StoryLine("크레스","그래서 증거를 가져왔어. 네 힘을 빼앗는 건 우리가 아니라 변환 장치야."),new StoryLine("민트","핵을 닫으면 마나가 고향으로 돌아가요. 우리가 함께 확인했어요."),new StoryLine("다오스","그 증거를 지킬 힘부터 보여라. 이번에도 거짓이라면 물러서지 않겠다.")},new[]{new StoryLine("다오스","기록이 사실이라면 이해가 일치하는 동안만 힘을 빌려주겠다."),new StoryLine("크레스","네가 한 일을 잊겠다는 뜻은 아니야. 지금은 두 세계를 살릴 길을 지키겠어."),new StoryLine("민트","적이었던 사실과 함께 살릴 수 있는 내일은 다른 이야기니까요."),new StoryLine("기록","조건부 공조가 성립했다. 전용 무기의 마지막 시련이 순차적으로 열린다. 시련을 마치지 않아도 메인 여정은 계속된다.")}),
new CrossoverEpisode(15,"기록되지 않은 미래","executor","","기록고 돌파와 오르도의 목적 공개.",new[]{new StoryLine("경계의 집행관","기록 외 행동 확인. 경계선을 넘는 의지는 삭제한다."),new StoryLine("오르도","수많은 결말을 보았네. 모두를 보존하려면 변화 자체를 멈춰야 했어."),new StoryLine("알펜","살아 있는 사람을 멈춘 기록으로 바꾸는 게 네 구원이었나."),new StoryLine("제이드","기록고에서 귀환 좌표를 가져오겠습니다. 교차하는 절단선의 빈 구역을 확보하세요."),new StoryLine("나탈리아","미래는 누구도 대신 소유할 수 없어요. 그 기록을 우리에게 돌려주세요.")},new[]{new StoryLine("경계의 집행관","보존 명령… 연결 상실."),new StoryLine("제이드","우리가 불려온 순간의 좌표를 찾았습니다. 각자의 결전 이전으로 돌아갈 수 있어요."),new StoryLine("시온","그럼 남의 결말을 바꾸기 위해 죽은 사람을 데려온 게 아니라는 거네."),new StoryLine("크레스","우리가 앞으로 무엇을 할지는 돌아간 뒤에 결정하자. 지금은 모두를 여기서 꺼내야 해.")}),
new CrossoverEpisode(16,"돌아갈 곳이 있는 사람들","hyades","","변이형을 막으며 마지막 피난 행렬 호위. 무기 서브 최종 정리 구간.",new[]{new StoryLine("히아데스","경계가 내 몸을 바꿔도 너희를 놓치지는 않는다!"),new StoryLine("파라","저 힘에 휩쓸리면 피난 행렬도 위험해. 내가 앞에서 유인할게."),new StoryLine("키사라","혼자 두지는 않겠다. 마지막 행렬이 도착할 때까지 전열을 유지한다."),new StoryLine("민트","모두에게 돌아갈 곳이 있어요. 마지막 한 사람도 남기지 말아요.")},new[]{new StoryLine("파라","끝까지 왔어. 히아데스도 더는 쫓아오지 못해."),new StoryLine("키사라","피난 행렬 전원 확인. 이제 우리 차례다."),new StoryLine("벨벳","돌아가기 전에 끝낼 일이 남았지. 준비됐으면 움직여."),new StoryLine("기록","17화 반격 전에 동료들의 무기 시련을 정리할 수 있다. 남은 선택 임무는 이후에도 포기 처리되지 않는다.")}),
new CrossoverEpisode(17,"다섯 세계의 반격","vholran","","귀환 거점 확보와 지배 세력 돌파.",new[]{new StoryLine("볼란","경계까지 무너뜨려도 너는 내 지배를 벗어나지 못한다, 알펜."),new StoryLine("알펜","누군가를 지배해야만 설 수 있는 세계를 끝내겠어."),new StoryLine("시온","물결 뒤에 얼음이 따라와. 멈춰 서서 맞서지 마."),new StoryLine("크레스","다섯 세계의 통로를 지키자. 우리가 돌아갈 길은 함께 열어야 해.")},new[]{new StoryLine("볼란","그 자유가 너를 구할 거라 믿느냐!"),new StoryLine("알펜","구해 주길 기다리는 게 아니야. 내가 선택하고 책임질 거야."),new StoryLine("시온","귀환 거점은 확보했어. 이제 안쪽의 목소리를 따라가자."),new StoryLine("기록","각 세계의 힘은 서로 다른 원리를 유지한 채 변환 장치를 거슬러 흘렀다. 하나가 되지 않아도 함께 싸울 수 있었다.")}),
new CrossoverEpisode(18,"잃어버린 사람들의 목소리","shizel","","환영에서 동료 해방, 보호 구역을 연결해 오의 돌파.",new[]{new StoryLine("시젤","돌아갈 곳보다 잃어버린 사람의 목소리가 더 그립지 않으냐."),new StoryLine("파라","그 목소리로 친구를 가두지 마! 우리가 함께 돌아갈 거야."),new StoryLine("민트","보호 구역을 이어야 환영에서 빠져나올 수 있어요."),new StoryLine("티아","노래로 신호를 보낼게. 자기 이름을 들으면 우리 쪽으로 와."),new StoryLine("크레스","시젤만 쓰러뜨리고 끝낼 수는 없어. 갇힌 동료부터 구하자.")},new[]{new StoryLine("파라","모두 정신 차렸어. 없는 사람의 목소리가 지금 곁에 있는 친구를 대신할 수는 없어."),new StoryLine("시젤","그 손을 끝까지 놓지 않을 수 있겠느냐…"),new StoryLine("티아","환영이 걷혔어. 각자의 슬픔까지 지워진 것은 아니지만, 혼자는 아니야."),new StoryLine("기록","동료를 모두 해방한 뒤 귀환로가 열렸다. 시젤의 뒤에 드러난 그림자는 별도의 인물로 기록되지 않는다.")}),
new CrossoverEpisode(19,"영원을 멈추는 전투","artorius","","최종 결전과 봉인망 차단. 희생 강요 없이 오르도에게 이르는 길 확보.",new[]{new StoryLine("아르토리우스","감정을 남겨 두는 한 희생은 반복된다. 여기서 끝내겠다."),new StoryLine("벨벳","네가 정한 평온을 위해 누군가를 버리게 두지는 않겠어."),new StoryLine("키사라","봉인망을 끊는 동안 전열을 지킨다. 누구도 제물로 남기지 않는다."),new StoryLine("민트","멈춘 시간을 다시 움직일게요. 그 순간 준비 공격을 끊어 주세요."),new StoryLine("아르토리우스","그 의지가 끝까지 견디는지 보여라.")},new[]{new StoryLine("벨벳","오늘 우리가 지킨 사람들을 네 계산에서 지우지 마."),new StoryLine("아르토리우스","너희가 선택한 감정의 끝을… 보겠노라."),new StoryLine("알펜","봉인망이 멈췄어. 모두 함께 오르도에게 갈 수 있어."),new StoryLine("기록","기본 인간형 아르토리우스와의 결전을 마쳤다. 원래 세계에 남은 그의 결말과 이 경계에서의 퇴장은 구분된다.")}),
new CrossoverEpisode(20,"각자의 하늘, 같은 약속","ordo","","3단계 최종전. 귀환 장치 연결과 각자의 세계로 돌아가는 결말.",new[]{new StoryLine("오르도","관찰도 봉합도 실패했다. 이제 귀환 자체를 멈추겠다."),new StoryLine("제이드","기록 재생, 인과 왜곡, 귀환 봉쇄. 세 층의 장치를 순서대로 끊어야 합니다."),new StoryLine("크레스","우리 미래가 두렵다고 우리 대신 멈출 수는 없어!"),new StoryLine("민트","돌아가서 다시 만날 사람들을 위해, 지금 이 시간을 지킬게요."),new StoryLine("오르도","그렇다면 기록되지 않은 답을 내게 보여 주게.")},new[]{new StoryLine("오르도","끝을 알 수 없는 미래를… 그래도 선택하는가."),new StoryLine("크레스","알 수 없으니까 우리가 걸어가는 거야. 모두 각자의 하늘로 돌아가자."),new StoryLine("민트","크레스 씨, 준비됐어요. 우리가 만났다는 기억은 가지고 갈 수 있어요."),new StoryLine("파라","다음에 만나면 같이 밥 먹자! 어떤 하늘 아래라도 약속이야."),new StoryLine("티아","제이드, 나탈리아. 돌아가서 해야 할 일을 계속하자."),new StoryLine("제이드","이번에는 기록만으로 사람을 판단하지 않도록 하겠습니다."),new StoryLine("나탈리아","이름도 나라 이름도 달랐지만, 모두 지켜야 할 사람들이었어요."),new StoryLine("벨벳","내 길은 내가 가. 그래도… 여기서 같이 싸운 건 잊지 않겠어."),new StoryLine("알펜","시온, 키사라. 우리 세계로 돌아가자. 남은 내일을 바꾸러."),new StoryLine("시온","알아. 이번에는 혼자 가겠다고 하지 않을게."),new StoryLine("키사라","마지막까지 전원 확인. 귀환을 시작한다."),new StoryLine("기록 · 에필로그","열 명은 각자의 결전 이전 시점으로 돌아갔다. 오르도의 변환 장치는 멈추고 세계의 원리는 다시 분리되었다. 결말을 미리 받지는 않았지만, 서로 다른 세계에서도 손을 잡을 수 있다는 기억은 남았다. 경계를 잇는 의지 — 끝.")}),
}; } }
